sys_script.script:
(function executeRule(current, previous) {
  var t = new SUCMTriage();
  var text = current.getValue('title') + ' ' + current.getValue('description');
  var lat = parseFloat(current.getValue('latitude')) || 0;
  var lng = parseFloat(current.getValue('longitude')) || 0;

  var cls = t.classify(text);
  current.department = cls.dept;
  current.category = cls.cat;
  current.status = 'new';
  current.number = t.nextNumber();

  // duplicate detection: oldest open similar report becomes the parent
  var similar = t.similarOpen(cls.cat, lat, lng);
  var count = similar.getRowCount();
  var parentId = '';
  if (similar.next()) {
    parentId = similar.parent_issue.nil() ? similar.getUniqueValue() : similar.getValue('parent_issue');
  }
  if (parentId) current.parent_issue = parentId;

  var sc = t.score(text, count, lat, lng);
  current.priority = sc.priority;
  var note = 'rule-based classifier (no AI API configured); score ' + sc.score + (sc.why ? ' (' + sc.why + ')' : '');
  if (!cls.matched) note += '; needs human review';
  if (sc.priority === 'critical') note += '; CRITICAL: officer must confirm';
  current.ai_method = note;

  // raise the parent's priority if this report makes it more serious
  if (parentId) {
    var order = {low: 0, medium: 1, high: 2, critical: 3};
    var p = new GlideRecord('x_2258429_smart_0_civic_issue');
    if (p.get(parentId) && order[sc.priority] > order[p.getValue('priority')]) {
      p.priority = sc.priority;
      p.update();
    }
  }
})(current, previous);
